// This strategy aims to solve math word problems involving arithmetic operations on symbolic quantities. 
// It iteratively generates tokens based on a combination of unconstrained steps and constrained steps 
// guided by the problem's structure and grammar rules. The goal is to produce a valid solution within 
// the given maximum number of steps while respecting the problem's syntax and semantics.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var currentConstrained: Prefix := [];
while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  decreases maxSteps - steps
{{
  // Check if the current generated prefix forms a valid intermediate step
  var narrow := helpers.DeadEndDetection(parser, currentConstrained, 2);
  if narrow {
    // If the current path is invalid, backtrack to the last valid state
    var rolledBack := helpers.RollbackToValidPrefix(parser, currentConstrained);
    currentConstrained := rolledBack;
    helpers.cost := helpers.cost + 1; // Increment cost for the rollback operation
    continue; // Restart the loop to explore other possible paths
  }

  // If the problem is almost solved, use a more confident approach
  if helpers.CountSubstring(helpers.PrefixToString(currentConstrained), "=") >= 1 {
    var next := helpers.ConstrainedStep(lm, parser, currentConstrained, currentConstrained);
    generated := generated + [next];
    steps := steps + 1;
    continue;
  }

  // Otherwise, take an unconstrained step to explore new possibilities
  var next := helpers.UnconstrainedStep(lm, currentConstrained, generated);
  if next == eosToken {
    break;
